<?php
declare(strict_types=1);

function get_string(string $key,string $default=''): string { return is_string($_GET[$key] ?? null)?$_GET[$key]:$default; }
function view_login(): void {
    if(user())redirect('dashboard');head('Business login','auth-body'); ?>
<main id="main" class="auth-wrap"><a class="brand auth-brand" href="<?=e(url())?>"><span class="brand-mark"><?=icon('calendar')?></span>BookNest</a><div class="auth-card"><span class="eyebrow">WELCOME BACK</span><h1>A little more<br>order in your day.</h1><p class="muted">Sign in to manage your appointments and team.</p><?php flashes();?><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="login"><?php field('email','Email address','','email');field('password','Password','','password');?><button class="button button-full">Sign in<?=icon('arrow')?></button></form><p class="small muted auth-note">Need to reset your password? Follow the owner recovery steps in your installation guide.</p></div><a class="back-link" href="<?=e(url())?>">← Back to booking page</a></main>
<?php foot(); }

function booking_summary(?array $service, ?array $staff, string $date='', string $time=''): void { ?>
<aside class="booking-summary"><div class="summary-brand"><span class="business-monogram"><?=e(short_name(setting('business_name')))?></span><span class="eyebrow">A LITTLE TIME, JUST FOR YOU</span><h2><?=e(setting('business_name'))?></h2><p><?=e(setting('tagline','Make time for what matters. Book your next appointment in a few simple steps.'))?></p></div><div class="summary-content"><div class="summary-title">Your appointment</div><?php if($service):?><h3><?=e($service['name'])?></h3><ul class="detail-list"><li><?=icon('clock')?><span><?=(int)$service['duration_minutes']?> minutes</span></li><?php if($staff):?><li><?=icon('people')?><span><?=e($staff['name'])?></span></li><?php endif;if($date):?><li><?=icon('calendar')?><span><?=e(parse_local($date,$time ?: '00:00')->format('D, j M Y'))?><?=$time?' · '.e(parse_local($date,$time)->format('g:i a')):''?></span></li><?php endif;?></ul><div class="summary-total"><span>Total</span><strong><?=e(money((int)$service['price_minor']))?></strong></div><p class="small muted">Payment is arranged directly with the business.</p><?php else:?><div class="summary-placeholder"><?=icon('calendar')?><p>Choose a service to start<br>planning your visit.</p></div><?php endif;?><div class="summary-contact"><?php if(setting('address')!==''):?><p><?=icon('location')?><span><?=e(setting('address'))?></span></p><?php endif;if(setting('phone')!==''):?><p><span>Questions? <?=e(setting('phone'))?></span></p><?php endif;?><p class="small muted">All times in <?=e(setting('timezone'))?></p></div></div></aside>
<?php }

function view_book(): void {
    rate_limit('booking-page',400);
    $serviceId=(int)get_string('service');$service=$serviceId?service_by_id($serviceId):null;
    $staffList=$service?service_staff($serviceId):[];$staffId=(int)get_string('staff',(string)($staffList[0]['id'] ?? 0));$staff=null;
    foreach($staffList as $s)if((int)$s['id']===$staffId)$staff=$s;
    $date=get_string('date',local_now()->format('Y-m-d'));
    if(!date_allowed($date))$date=local_now()->format('Y-m-d');
    try{parse_local($date,'00:00');}catch(ValidationError){$date=local_now()->format('Y-m-d');}
    $time=get_string('time');$slots=$service && $staff?available_slots($service,$staffId,$date):[];$selected=null;
    foreach($slots as $slot)if($slot['time']===$time)$selected=$slot;
    $step=$service?($selected?3:2):1;
    head('Book an appointment','public-body');public_header(); ?>
<main id="main" class="booking-main"><div class="booking-intro"><p class="eyebrow"><?=icon('spark')?> A MOMENT TO LOOK FORWARD TO</p><h1>Your time. Your next appointment.</h1><p>Choose what you need. Find a time that fits. We’ll take it from there.</p></div><div class="booking-layout"><section class="booking-panel"><ol class="booking-steps" aria-label="Booking progress"><?php foreach([1=>'Service',2=>'Date & time',3=>'Your details'] as $n=>$label):?><li class="<?=$step===$n?'current':($step>$n?'done':'')?>" <?=$step===$n?'aria-current="step"':''?>><span><?=$step>$n?icon('check'):$n?></span><?=$label?></li><?php endforeach;?></ol><?php flashes();?>
<?php if($step===1):?>
<div class="section-heading"><div><span class="step-kicker">LET’S START HERE</span><h2>What can we help you with?</h2><p class="muted">Select a service to see available appointments.</p></div></div><div class="service-list"><?php $services=rows('SELECT s.* FROM bk_services s WHERE active=1 AND EXISTS (SELECT 1 FROM bk_service_staff ss JOIN bk_staff st ON st.id=ss.staff_id WHERE ss.service_id=s.id AND st.active=1) ORDER BY s.id');foreach($services as $i=>$sv):?><a class="service-card" href="<?=e(url('book',['service'=>$sv['id']]))?>"><span class="service-icon service-tone-<?=$i%3?>"><?=icon(['service','people','spark'][$i%3])?></span><div class="service-card-copy"><h3><?=e($sv['name'])?></h3><?php if($sv['description']):?><p><?=e($sv['description'])?></p><?php endif;?><span class="service-duration"><?=icon('clock')?><?=(int)$sv['duration_minutes']?> min</span></div><div class="service-card-end"><strong><?=e(money((int)$sv['price_minor']))?></strong><span class="round-arrow"><?=icon('arrow')?></span></div></a><?php endforeach;if(!$services)empty_state('Bookings are opening soon','Please contact the business to arrange your appointment.'); ?></div><div class="booking-help"><?=icon('lock')?><p>A few details. A time that works. A booking you can manage.</p></div>
<?php elseif($step===2):?>
<a class="back-link" href="<?=e(url())?>">← Change service</a><div class="section-heading"><div><span class="step-kicker">MAKE IT A DATE</span><h2>Find your perfect time.</h2><p class="muted">Availability is shown in <?=e(setting('timezone'))?>.</p></div></div>
<?php if(!$staffList):empty_state('No team members available','Please contact the business for help booking this service.');else:?>
<form method="get" class="slot-filter"><input type="hidden" name="page" value="book"><input type="hidden" name="service" value="<?=$serviceId?>"><?php select_field('staff','Team member',array_column($staffList,'name','id'),$staffId);?><label class="field"><span>Choose a date</span><input type="date" name="date" value="<?=e($date)?>" min="<?=e(local_now()->format('Y-m-d'))?>" max="<?=e(local_now()->modify('+'.(int)setting('booking_window_days','60').' days')->format('Y-m-d'))?>" required></label><button class="button button-ghost">Show times</button></form>
<div class="date-strip"><?php $start=local_now()->setTime(0,0);for($i=0;$i<7;$i++):$d=$start->modify('+'.$i.' days');if(!date_allowed($d->format('Y-m-d')))break;?><a class="date-card <?=$date===$d->format('Y-m-d')?'selected':''?>" href="<?=e(url('book',['service'=>$serviceId,'staff'=>$staffId,'date'=>$d->format('Y-m-d')]))?>"><span><?=$d->format('D')?></span><strong><?=$d->format('j')?></strong><small><?=$d->format('M')?></small></a><?php endfor;?></div><h3 class="slot-heading"><?=e(parse_local($date,'00:00')->format('l, j F'))?><span><?=count($slots)?> available</span></h3><div class="time-grid"><?php foreach($slots as $slot):?><a class="time-slot" href="<?=e(url('book',['service'=>$serviceId,'staff'=>$staffId,'date'=>$date,'time'=>$slot['time']]))?>"><?=e($slot['label'])?></a><?php endforeach;?></div><?php if(!$slots)empty_state('A little busy on this day','Try another date or team member to find an available time.','clock');endif;?>
<?php else:
    $nonce=bin2hex(random_bytes(16));$_SESSION['booking_nonces'][$nonce]=time();if(count($_SESSION['booking_nonces'])>10)array_shift($_SESSION['booking_nonces']);$old=$_SESSION['booking_old'] ?? [];
?>
<a class="back-link" href="<?=e(url('book',['service'=>$serviceId,'staff'=>$staffId,'date'=>$date]))?>">← Choose another time</a><div class="section-heading"><div><span class="step-kicker">ALMOST THERE</span><h2>Make it yours.</h2><p class="muted">Tell us a little about yourself to complete your booking.</p></div></div><div class="selected-slot"><?=icon('calendar')?><div><strong><?=e(parse_local($date,$time)->format('l, j F · g:i a'))?></strong><span><?=e($service['name'])?> with <?=e($staff['name'])?></span></div><?=icon('check')?></div><form method="post" class="stack booking-details"><?=csrf_field()?><input type="hidden" name="action" value="book"><input type="hidden" name="nonce" value="<?=e($nonce)?>"><input type="hidden" name="service_id" value="<?=$serviceId?>"><input type="hidden" name="staff_id" value="<?=$staffId?>"><input type="hidden" name="date" value="<?=e($date)?>"><input type="hidden" name="time" value="<?=e($time)?>"><div class="honeypot" aria-hidden="true"><label>Leave this empty<input type="text" name="website" tabindex="-1" autocomplete="off"></label></div><?php field('client_name','Full name',$old['client_name'] ?? '');?><div class="form-grid"><?php field('client_phone','Phone number',$old['client_phone'] ?? '','tel',true,'Include your country code, e.g. +92.');field('client_email','Email address',$old['client_email'] ?? '','email',false);?></div><?php textarea_field('notes','Anything we should know? (optional)',is_string($old['notes'] ?? null)?$old['notes']:'');?><div class="policy-note"><strong>Before you book</strong><p><?=e(setting('cancellation_policy','Please give us advance notice if your plans change.'))?></p><p>You can change or cancel online until <?=(int)setting('cancellation_notice_minutes','120')?> minutes before your appointment.</p></div><button class="button button-full"><?=setting('auto_confirm','1')==='1'?'Confirm appointment':'Request appointment'?><?=icon('arrow')?></button><p class="small muted text-center">Save the confirmation link after booking. You’ll use it to manage your visit.</p></form>
<?php endif;?></section><?php booking_summary($service,$staff,$service?$date:'',$selected?$time:'');?></div></main><?php public_footer();foot();
}

function view_manage(): void {
    rate_limit('manage-page',120);$token=get_string('token');$b=booking_for_token($token);
    if(!$b){http_response_code(404);head('Booking not found','public-body');public_header();echo '<main id="main" class="narrow-main">';empty_state('We couldn’t find that booking','Open the complete confirmation link saved when you booked.');echo '</main>';public_footer();foot();return;}
    $paid=payment_total((int)$b['id']);$can=can_customer_change($b);head('Your appointment','public-body');public_header(); ?>
<main id="main" class="receipt-main"><?php flashes();?><div class="receipt-heading"><span class="success-orb"><?=icon($b['status']==='cancelled'?'calendar':'check')?></span><p class="eyebrow">A LITTLE SOMETHING TO LOOK FORWARD TO</p><h1><?=$b['status']==='cancelled'?'Your booking is cancelled.':($b['status']==='pending'?'Your request is with us.':'Your appointment, all in one place.')?></h1><p class="muted"><?=$b['status']==='pending'?'Please wait for the business to confirm your request.':'Keep this page handy for your appointment details.'?></p></div><section class="receipt-card"><div class="receipt-card-top"><span class="receipt-brand"><?=icon('calendar')?><?=e(setting('business_name'))?></span><?=status_badge($b['status'])?></div><div class="receipt-service"><p class="eyebrow">BOOKING <?=e($b['reference'])?></p><h2><?=e($b['service_name'])?></h2><p class="muted">with <?=e($b['staff_name'])?></p></div><div class="receipt-grid"><div><?=icon('calendar')?><span>Date & time<strong><?=e(local_date($b['starts_at'],'l, j F Y'))?><br><?=e(local_date($b['starts_at'],'g:i a'))?>–<?=e(local_date($b['ends_at'],'g:i a'))?></strong><small><?=e(setting('timezone'))?></small></span></div><div><?=icon('people')?><span>Booked for<strong><?=e($b['client_name'])?></strong><small><?=e($b['client_phone'])?></small></span></div></div><dl class="receipt-money"><div><dt>Appointment total</dt><dd><?=e(money((int)$b['price_minor'],$b['currency_code']))?></dd></div><div><dt>Payment recorded</dt><dd><?=e(money($paid,$b['currency_code']))?></dd></div><div class="balance"><dt><?=$b['status']==='cancelled'?'Retained payment':'Remaining balance'?></dt><dd><?=e(money($b['status']==='cancelled'?$paid:max(0,(int)$b['price_minor']-$paid),$b['currency_code']))?></dd></div></dl><?php if($b['status']==='cancelled' && $paid>0):?><div class="notice notice-info">Please contact the business to arrange any refund. Cancelling a booking does not transfer money.</div><?php endif;?><?php if(setting('payment_instructions')!=='' && $b['status']!=='cancelled'):?><div class="payment-note"><strong>Payment details</strong><p><?=nl2br(e(setting('payment_instructions')))?></p><small>The business will update your payment status after checking receipt.</small></div><?php endif;?><div class="receipt-actions"><?php if($b['status']!=='cancelled'):?><a class="button button-ghost" href="<?=e(url('calendar',['token'=>$token]))?>"><?=icon('calendar')?>Add to calendar</a><?php endif;?><button class="button button-ghost" type="button" data-copy="<?=e(absolute_url('manage',['token'=>$token]))?>"><?=icon('copy')?>Copy booking link</button><button class="button button-ghost" type="button" data-print>Print details</button></div><details class="link-backup"><summary>View your private booking link</summary><p class="small muted">Keep this link private. It allows changes to this booking.</p><input class="copy-input" readonly value="<?=e(absolute_url('manage',['token'=>$token]))?>" aria-label="Private booking link"></details></section><div class="receipt-bottom"><?php if($can):?><a class="button button-ghost" href="<?=e(url('move',['token'=>$token]))?>">Change appointment</a><form method="post" data-confirm="Cancel this appointment? Any refund must be arranged with the business."><?=csrf_field()?><input type="hidden" name="action" value="customer_cancel"><input type="hidden" name="token" value="<?=e($token)?>"><button class="text-button danger-text">Cancel booking</button></form><?php elseif(in_array($b['status'],['pending','confirmed'],true)):?><p class="small muted">To change this appointment, please contact the business.</p><?php endif;?></div><?php if(setting('whatsapp')!==''):$message='Hello, I have a question about booking '.$b['reference'].' for '.$b['service_name'].' on '.local_date($b['starts_at']).'.';?><a class="contact-link" href="https://wa.me/<?=e(setting('whatsapp'))?>?text=<?=e(rawurlencode($message))?>" rel="noopener" target="_blank">Contact <?=e(setting('business_name'))?> on WhatsApp<?=icon('external')?></a><?php endif;?><a class="back-link text-center" href="<?=e(url())?>">Book another appointment →</a></main><?php public_footer();foot();
}

function view_move(): void {
    $token=get_string('token');$admin=$token==='';$id=(int)get_string('id');if($admin)require_user();else rate_limit('move-page',100);
    $b=$admin?one('SELECT a.*,s.name AS staff_name FROM bk_appointments a JOIN bk_staff s ON s.id=a.staff_id WHERE a.id=?',[$id]):booking_for_token($token);
    if(!$b || !in_array($b['status'],['pending','confirmed'],true) || (!$admin && !can_customer_change($b))){flash('This appointment cannot be changed online. Please contact the business.','error');redirect($admin?'appointments':'manage',$admin?[]:['token'=>$token]);}
    $service=service_by_id((int)$b['service_id']);
    if(!$service){flash('This service is no longer available online. Please contact the business.','error');redirect($admin?'appointment':'manage',$admin?['id'=>$b['id']]:['token'=>$token]);}
    $service['duration_minutes']=$b['duration_minutes'];$service['buffer_minutes']=$b['buffer_minutes'];$staffList=service_staff((int)$b['service_id']);$staffId=(int)get_string('staff',(string)$b['staff_id']);$date=get_string('date',local_date($b['starts_at'],'Y-m-d'));
    if(!date_allowed($date))$date=local_now()->format('Y-m-d');$slots=available_slots($service,$staffId,$date,$admin,(int)$b['id']);head('Change appointment','public-body');public_header(); ?>
<main id="main" class="narrow-main"><a class="back-link" href="<?=e(url($admin?'appointment':'manage',$admin?['id'=>$b['id']]:['token'=>$token]))?>">← Back to appointment</a><p class="eyebrow">A CHANGE OF PLANS</p><h1>Find a new time.</h1><p class="muted"><?=e($b['service_name'])?> · <?=e($b['reference'])?>. Your price and duration stay the same.</p><?php flashes();?><section class="panel"><form method="get" class="slot-filter"><input type="hidden" name="page" value="move"><input type="hidden" name="<?=$admin?'id':'token'?>" value="<?=e($admin?(string)$b['id']:$token)?>"><?php select_field('staff','Team member',array_column($staffList,'name','id'),$staffId);?><label class="field"><span>Date</span><input type="date" name="date" value="<?=e($date)?>" min="<?=e(local_now()->format('Y-m-d'))?>" max="<?=e(local_now()->modify('+'.(int)setting('booking_window_days','60').' days')->format('Y-m-d'))?>" required></label><button class="button button-ghost">Show times</button></form><p class="small muted">All times in <?=e(setting('timezone'))?>.</p><div class="time-grid"><?php foreach($slots as $slot):?><form method="post" data-confirm="Move your appointment to <?=e(parse_local($date,$slot['time'])->format('j M Y, g:i a'))?>?"><?=csrf_field()?><input type="hidden" name="action" value="move"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><input type="hidden" name="staff_id" value="<?=$staffId?>"><input type="hidden" name="date" value="<?=e($date)?>"><input type="hidden" name="time" value="<?=e($slot['time'])?>"><button class="time-slot"><?=e($slot['label'])?></button></form><?php endforeach;?></div><?php if(!$slots)empty_state('No available times','Try another date or team member.','clock');?></section></main><?php public_footer();foot();
}

function ics_text(string $s): string { return str_replace(["\\","\r\n","\r","\n",',',';'],['\\\\','\\n','\\n','\\n','\\,','\\;'],$s); }
function download_calendar(): void {
    rate_limit('calendar',100);$b=booking_for_token(get_string('token'));if(!$b){http_response_code(404);echo 'Booking not found.';return;}
    $lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//BookNest//Appointments//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'.$b['reference'].'@booknest.local','DTSTAMP:'.gmdate('Ymd\THis\Z'),'DTSTART:'.gmdate('Ymd\THis\Z',strtotime($b['starts_at'].' UTC')),'DTEND:'.gmdate('Ymd\THis\Z',strtotime($b['ends_at'].' UTC')),'SUMMARY:'.ics_text($b['service_name'].' · '.setting('business_name')),'DESCRIPTION:'.ics_text('Booking '.$b['reference'].' with '.$b['staff_name'].'. Contact: '.setting('phone')),'LOCATION:'.ics_text(setting('address')),'STATUS:'.($b['status']==='cancelled'?'CANCELLED':($b['status']==='pending'?'TENTATIVE':'CONFIRMED')),'END:VEVENT','END:VCALENDAR'];
    $folded=[];foreach($lines as $line){$chunk='';foreach(preg_split('//u',$line,-1,PREG_SPLIT_NO_EMPTY) ?: [] as $char){if(strlen($chunk)+strlen($char)>73){$folded[]=$chunk;$chunk=' ';}$chunk.=$char;}$folded[]=$chunk;}
    header('Content-Type: text/calendar; charset=utf-8');header('Content-Disposition: attachment; filename="'.$b['reference'].'.ics"');echo implode("\r\n",$folded)."\r\n";
}
